<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import SmisTopBar from './SmisTopBar.vue'
import SmisStatusTag from './SmisStatusTag.vue'
import SmisIcon from './SmisIcon.vue'
import { useAuthStore } from '@/stores/auth'
import { useProfileStore } from '@/stores/profile'
import { getHazardInspectionTask, getRiskTask, saveHazardInspectionExecution, saveRiskExecution } from '@/api/smis'
import type { HazardInspectionTaskDetail, InspectionTaskItem, RiskTaskDetail } from '@/api/types'
import { formatDate } from '@/utils/format'
import { getErrorMessage } from '@/api/supabase'
const props=defineProps<{kind:'risk'|'inspection'}>();const auth=useAuthStore();const profile=useProfileStore();const loading=ref(true);const saving=ref(false);const detail=ref<RiskTaskDetail|HazardInspectionTaskDetail|null>(null);const summary=ref('')
const canEdit=computed(()=>detail.value&&!['completed','cancelled'].includes(detail.value.status));const checked=computed(()=>detail.value?.items.filter(x=>x.result!=='pending').length||0);const abnormal=computed(()=>detail.value?.items.filter(x=>x.result==='abnormal').length||0)
async function load(id:string){if(!(await auth.ensureValidSession()))return;loading.value=true;try{await profile.load(auth.token);detail.value=props.kind==='risk'?await getRiskTask(auth.token,id):await getHazardInspectionTask(auth.token,id);summary.value=detail.value?.executionSummary||''}catch(e){uni.showToast({title:getErrorMessage(e),icon:'none'})}finally{loading.value=false}}
function setResult(item:InspectionTaskItem,result:'normal'|'abnormal'){if(!canEdit.value)return;item.result=result}
async function save(complete:boolean){if(!detail.value)return;if(complete&&checked.value<detail.value.items.length)return uni.showToast({title:'请完成全部检查项后再提交',icon:'none'});if(complete&&abnormal.value&&!detail.value.items.filter(x=>x.result==='abnormal').every(x=>x.remark?.trim()))return uni.showToast({title:'请填写异常项说明',icon:'none'});saving.value=true;try{if(props.kind==='risk'){const risk=detail.value as RiskTaskDetail;const employeeId=profile.profile?.employeeId||risk.actualExecutorEmployeeId||risk.assigneeEmployeeId;if(!employeeId)throw new Error('当前账号未关联员工档案');await saveRiskExecution(auth.token,{id:risk.id,actualExecutorEmployeeId:employeeId,executionSummary:summary.value,attachmentUrls:risk.attachmentUrls||[],items:risk.items,complete})}else{const hazard=detail.value as HazardInspectionTaskDetail;await saveHazardInspectionExecution(auth.token,{id:hazard.id,executionSummary:summary.value,attachmentUrls:hazard.attachmentUrls||[],items:hazard.items,complete})}uni.showToast({title:complete?'任务已完成':'进度已保存',icon:'success'});await load(detail.value.id)}catch(e){uni.showToast({title:getErrorMessage(e,'保存失败'),icon:'none'})}finally{saving.value=false}}
onLoad(query=>load(String(query?.id||'')))
</script>
<template><view class="page-shell"><SmisTopBar :title="kind==='risk'?'风险巡查执行':'隐患排查执行'" :subtitle="detail?.taskNo" show-back/><view class="page-body detail-body"><view v-if="loading" class="loading"><wd-loading color="#4f46e5"/></view><template v-else-if="detail"><view class="task-head surface-card"><view><SmisStatusTag :status="detail.status"/><text class="task-head__type">{{kind==='risk'?'风险巡查':'隐患排查'}}</text></view><text class="task-head__title">{{kind==='risk'?(detail as RiskTaskDetail).riskPointName:(detail as HazardInspectionTaskDetail).inspectionObject}}</text><view class="task-head__dates"><view><text>计划开始</text><text class="strong">{{formatDate(detail.plannedStartAt,true)}}</text></view><view class="i"/><view><text>计划完成</text><text class="strong">{{formatDate(detail.plannedEndAt,true)}}</text></view></view></view><view class="progress surface-card"><view><text>检查进度</text><text class="strong">{{checked}} / {{detail.items.length}}</text></view><view class="progress__bar"><view class="i" :style="{width:`${detail.items.length?checked/detail.items.length*100:0}%`}"/></view><text v-if="abnormal" class="progress__danger">已发现 {{abnormal}} 项异常</text><text v-else>现场结果实时保存</text></view><view class="section-head"><text>检查项目</text><text class="small">逐项确认，异常必须说明</text></view><view class="items"><view v-for="(item,index) in detail.items" :key="item.id" class="check-item surface-card" :class="{'check-item--abnormal':item.result==='abnormal'}"><view class="check-item__head"><text>{{String(index+1).padStart(2,'0')}}</text><view><text class="small">{{item.standardName||item.standardCode||'检查标准'}}</text><text class="strong">{{item.inspectionContent}}</text></view></view><view class="result-actions"><button :class="{'is-active is-normal':item.result==='normal'}" :disabled="!canEdit" @tap="setResult(item,'normal')"><SmisIcon name="check" size="28rpx"/>正常</button><button :class="{'is-active is-abnormal':item.result==='abnormal'}" :disabled="!canEdit" @tap="setResult(item,'abnormal')"><SmisIcon name="notice" size="28rpx"/>异常</button></view><textarea v-if="item.result==='abnormal'" v-model="item.remark" name="inspection-abnormal-remark" aria-label="异常情况说明" :disabled="!canEdit" auto-height maxlength="300" placeholder="请描述异常情况、位置与建议措施"/></view></view><view class="summary-field surface-card"><text>执行小结</text><textarea v-model="summary" name="inspection-summary" aria-label="执行小结" :disabled="!canEdit" auto-height maxlength="500" placeholder="填写本次巡查的整体情况（选填）"/></view><view v-if="canEdit" class="action-bar"><button :disabled="saving" @tap="save(false)">保存进度</button><button :disabled="saving" @tap="save(true)">完成并提交</button></view><view v-else class="closed-note"><SmisIcon name="check" size="34rpx"/><text>该任务已结束，检查结果与操作记录已固化留痕。</text></view></template><view v-else class="loading">任务不存在或无权查看</view></view></view></template>
<style scoped lang="scss">.detail-body{padding-bottom:calc(150rpx + env(safe-area-inset-bottom))}.loading{min-height:340rpx;display:flex;align-items:center;justify-content:center;color:var(--smis-text-muted)}.task-head{margin-top:-40rpx;padding:26rpx}.task-head>view:first-child{display:flex;align-items:center;gap:12rpx}.task-head__type{color:var(--smis-text-muted);font-size:20rpx}.task-head__title{display:block;margin-top:16rpx;font-size:30rpx;font-weight:700;line-height:1.45}.task-head__dates{margin-top:22rpx;padding-top:18rpx;border-top:1rpx solid var(--smis-line);display:grid;grid-template-columns:1fr 1rpx 1fr;gap:20rpx}.task-head__dates>view{display:flex;flex-direction:column}.task-head__dates text{font-size:19rpx;color:var(--smis-text-muted)}.task-head__dates .strong{margin-top:5rpx;font-size:21rpx}.task-head__dates .i{background:var(--smis-line)}.progress{margin-top:16rpx;padding:23rpx}.progress>view:first-child{display:flex;align-items:center;justify-content:space-between}.progress>view text{font-size:22rpx;color:var(--smis-text-secondary)}.progress>view .strong{font-size:26rpx;color:var(--smis-primary)}.progress__bar{height:12rpx;margin:16rpx 0 10rpx;border-radius:999rpx;background:#e8edf0;overflow:hidden}.progress__bar .i{display:block;height:100%;border-radius:999rpx;background:var(--smis-primary)}.progress>text{font-size:19rpx;color:var(--smis-text-muted)}.progress .progress__danger{color:var(--smis-danger)}.section-head{margin:30rpx 4rpx 16rpx;display:flex;align-items:flex-end;justify-content:space-between}.section-head text{font-size:29rpx;font-weight:700}.section-head .small{color:var(--smis-text-muted);font-size:19rpx}.items{display:flex;flex-direction:column;gap:15rpx}.check-item{padding:24rpx}.check-item--abnormal{border-left:7rpx solid var(--smis-danger)}.check-item__head{display:flex;align-items:flex-start;gap:16rpx}.check-item__head>text{width:46rpx;height:46rpx;border-radius:14rpx;background:var(--smis-primary-soft);color:var(--smis-primary);font-size:19rpx;font-weight:700;display:flex;align-items:center;justify-content:center}.check-item__head>view{min-width:0;flex:1;display:flex;flex-direction:column}.check-item__head .small{font-size:18rpx;color:var(--smis-text-muted)}.check-item__head .strong{margin-top:7rpx;font-size:24rpx;line-height:1.5}.result-actions{margin-top:22rpx;display:grid;grid-template-columns:1fr 1fr;gap:12rpx}.result-actions button{min-height:76rpx;margin:0;border-radius:17rpx;background:#f2f5f7;color:var(--smis-text-secondary);font-size:22rpx;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8rpx}.result-actions .is-normal{background:#e5f3ec;color:var(--smis-success)}.result-actions .is-abnormal{background:#fbe9e8;color:var(--smis-danger)}.check-item textarea,.summary-field textarea{width:100%;min-height:100rpx;margin-top:16rpx;padding:17rpx;border-radius:15rpx;background:#f6f8f9;font-size:22rpx;line-height:1.5}.summary-field{margin-top:18rpx;padding:24rpx}.summary-field>text{font-size:25rpx;font-weight:700}.action-bar{position:fixed;z-index:20;left:0;right:0;bottom:0;padding:16rpx 24rpx calc(16rpx + env(safe-area-inset-bottom));background:rgba(255,255,255,.95);box-shadow:0 -10rpx 30rpx rgba(31,59,76,.10);display:grid;grid-template-columns:1fr 1.6fr;gap:14rpx}.action-bar button{min-height:88rpx;margin:0;border-radius:18rpx;background:#e9f0f4;color:var(--smis-primary);font-size:25rpx;font-weight:700}.action-bar button:last-child{background:var(--smis-hero-gradient);color:#fff}.closed-note{margin-top:18rpx;padding:22rpx;border-radius:18rpx;background:#e5f3ec;color:var(--smis-success);display:flex;align-items:flex-start;gap:13rpx;font-size:21rpx;line-height:1.5}</style>
